script:
const LIMIT = 8;
const esc = (s) => frappe.utils.escape_html(s == null ? "" : String(s));
const list = root_element.querySelector(".cs-list");
const meta = root_element.querySelector(".bx-meta");
const moreBtn = root_element.querySelector(".bx-more");
let rows = [];
let showAll = false;

const waitTag = (d) => {
  const txt = d + (d === 1 ? " day" : " days");
  if (d >= 10) return '<span class="tag red">' + txt + "</span>";
  if (d >= 5) return '<span class="tag amber">' + txt + "</span>";
  return '<span class="tag">' + txt + "</span>";
};

const row = (r) => '<div class="cs-grid">'
  + '<span class="bx-link" data-cs="' + esc(r.name) + '">' + esc(r.name) + "</span>"
  + "<span>" + esc(r.customer) + (r.subject ? ' <span class="cs-sub">&middot; ' + esc(r.subject) + "</span>" : "") + "</span>"
  + "<span>" + esc(r.sales_person) + "</span>"
  + (r.pricing_type ? '<span class="tag ' + r.pricing_type.toLowerCase() + '">' + esc(r.pricing_type) + "</span>" : "<span></span>")
  + waitTag(r.days) + "</div>";

const render = () => {
  if (!rows.length) {
    list.innerHTML = '<div class="bx-empty">Every submitted cost sheet has a quotation.</div>';
    moreBtn.hidden = true;
    return;
  }
  list.innerHTML = (showAll ? rows : rows.slice(0, LIMIT)).map(row).join("");
  moreBtn.hidden = rows.length <= LIMIT;
  moreBtn.textContent = showAll ? "Show fewer" : "Show all " + rows.length;
};

moreBtn.addEventListener("click", () => { showAll = !showAll; render(); });

list.addEventListener("click", (e) => {
  const c = e.target.closest("[data-cs]");
  if (c) frappe.set_route("Form", "Cost Sheet", c.dataset.cs);
});

frappe.xcall("bom_work_queue", { part: "cost_sheets" }).then((r) => {
  rows = r.rows || [];
  meta.textContent = rows.length ? rows.length + " waiting · oldest first" : "";
  render();
}).catch(() => {
  meta.textContent = "";
  list.innerHTML = '<div class="bx-empty">Couldn\'t load cost sheets. Check the BOM - Work Queue server script and Cost Sheet permissions.</div>';
});

