script:
const RED = "#E24C4C", ORANGE = "#F39C3D", BLUE = "#4C8BF5", GREY = "#8D99A6", GREEN = "#36A55A";
const cards = [
  { row: 0, label: "Job tickets pending BOM", color: RED, dt: "Production Plan",
    filters: { custom_needs_bom: 1, docstatus: ["<", 2] } },
  { row: 0, label: "NPD awaiting BOM", color: ORANGE, dt: "NPD Request",
    filters: { bom_confirmed: 0, docstatus: 1 } },
  { row: 0, label: "Products without BOM", color: ORANGE, dt: "Product Library", key: "products" },
  { row: 0, label: "Draft BOMs", color: GREY, dt: "BOM", filters: { docstatus: 0 } },
  { row: 1, label: "Cost sheets without quote", color: BLUE, dt: "Cost Sheet", key: "cost_sheets" },
  { row: 1, label: "Products pending validation", color: ORANGE, dt: "Product Library",
    filters: { approval_status: "Pending Validation" } },
  { row: 1, label: "Returned for correction", color: RED, dt: "Product Library",
    filters: { approval_status: "Returned for Correction" } },
  { row: 1, label: "BOMs created this month", color: GREEN, dt: "BOM",
    filters: { docstatus: 1, creation: [">=", frappe.datetime.month_start()] } },
];
const names = {};
const grids = root_element.querySelectorAll(".ks-grid");

cards.forEach((c) => {
  const el = document.createElement("button");
  el.className = "ks-card";
  el.title = c.label;
  el.innerHTML = '<div class="ks-l"></div><div class="ks-v">&hellip;</div>';
  el.querySelector(".ks-l").textContent = c.label;
  c.el = el.querySelector(".ks-v");
  c.el.style.color = c.color;
  el.addEventListener("click", () => {
    if (c.key) {
      const list = names[c.key] || [];
      frappe.route_options = { name: ["in", list.length ? list : ["-"]] };
    } else {
      frappe.route_options = Object.assign({}, c.filters);
    }
    frappe.set_route("List", c.dt);
  });
  grids[c.row].appendChild(el);
});

const show = (c, n) => { c.el.textContent = n == null ? "?" : Number(n).toLocaleString(); };

cards.filter((c) => !c.key).forEach((c) => {
  frappe.db.count(c.dt, { filters: c.filters }).then((n) => show(c, n)).catch(() => show(c, null));
});

frappe.xcall("bom_work_queue", { part: "counts" }).then((r) => {
  cards.filter((c) => c.key).forEach((c) => {
    names[c.key] = r[c.key] || [];
    show(c, names[c.key].length);
  });
}).catch(() => cards.filter((c) => c.key).forEach((c) => show(c, null)));

