script:
const LIMIT = 8;
const esc = (s) => frappe.utils.escape_html(s == null ? "" : String(s));
const list = root_element.querySelector(".bq-list");
const meta = root_element.querySelector(".bx-meta");
const moreBtn = root_element.querySelector(".bx-more");
let items = [];
let filter = "all";
let showAll = false;

const plural = (n, one, many) => n + " " + (n === 1 ? one : many);

const dueTag = (d, word) => {
  if (d === null || d === undefined) return { cls: "", tone: "grey", html: "" };
  if (d < 0) return { tone: "red", html: '<span class="tag red">' + plural(Math.abs(d), "day", "days") + " late</span>" };
  if (d === 0) return { tone: "red", html: '<span class="tag red">' + word + " today</span>" };
  if (d <= 3) return { tone: "amber", html: '<span class="tag amber">' + word + " in " + plural(d, "day", "days") + "</span>" };
  return { tone: "grey", html: '<span class="tag">' + word + " in " + d + " days</span>" };
};

const join = (parts) => parts.filter(Boolean).map(esc).join(" &middot; ");

const row = (it) => {
  let short, label, dt, t2, right, action, tone;
  if (it.kind === "ticket") {
    short = "JT"; label = "Job ticket"; dt = "Production Plan";
    const due = dueTag(it.days_left, "Needed");
    tone = due.tone;
    t2 = join([it.customer, it.title]) + " &middot; "
      + (it.pending ? plural(it.pending, "item has", "items have") + " no BOM" : "items pending BOM");
    right = due.html;
    action = it.so
      ? '<button class="bq-btn primary" data-builder="' + esc(it.so) + '">Open BOM builder</button>'
      : '<button class="bq-btn" data-dt="Production Plan" data-dn="' + esc(it.name) + '">Open job ticket</button>';
  } else if (it.kind === "npd") {
    short = "NPD"; label = "NPD request"; dt = "NPD Request";
    const due = dueTag(it.days_left, "Sample due");
    tone = due.tone === "grey" ? "amber" : due.tone;
    t2 = join([it.customer, it.title]) + (it.artwork_status ? " &middot; artwork " + esc(it.artwork_status).toLowerCase() : "");
    right = due.html;
    action = '<button class="bq-btn" data-dt="NPD Request" data-dn="' + esc(it.name) + '">Confirm BOM</button>';
  } else {
    short = "PL"; label = "Product library"; dt = "Product Library";
    tone = it.config_saved ? "blue" : "grey";
    t2 = join([it.customer, it.fg_item]) + (it.approval_status ? " &middot; " + esc(it.approval_status).toLowerCase() : "") + " &middot; no active BOM";
    right = it.config_saved
      ? '<span class="tag blue">Config saved</span>'
      : '<span class="tag">Waiting ' + plural(it.age, "day", "days") + "</span>";
    action = '<button class="bq-btn" data-newbom="' + esc(it.fg_item) + '">Create BOM</button>';
  }
  const title = it.kind === "product" && it.product_name ? esc(it.name) + " &middot; " + esc(it.product_name) : esc(it.name);
  const typeTag = it.pricing_type ? '<span class="tag ' + it.pricing_type.toLowerCase() + '">' + esc(it.pricing_type) + "</span>" : "";
  return '<div class="bq-row">'
    + '<div class="bq-ic ' + tone + '">' + short + "</div>"
    + '<div><div class="bq-t1"><span class="bx-link" data-dt="' + dt + '" data-dn="' + esc(it.name) + '">' + title + "</span>"
    + '<span class="tag">' + label + "</span>" + typeTag + "</div>"
    + '<div class="bq-t2">' + t2 + "</div></div>"
    + '<div class="bq-right">' + right + action + "</div></div>";
};

const render = () => {
  const shown = items.filter((i) => filter === "all" || i.kind === filter);
  if (!shown.length) {
    list.innerHTML = '<div class="bx-empty">Nothing waiting here.</div>';
    moreBtn.hidden = true;
    return;
  }
  list.innerHTML = (showAll ? shown : shown.slice(0, LIMIT)).map(row).join("");
  moreBtn.hidden = shown.length <= LIMIT;
  moreBtn.textContent = showAll ? "Show fewer" : "Show all " + shown.length + " items";
};

root_element.querySelectorAll(".bq-chip").forEach((chip) => {
  chip.addEventListener("click", () => {
    root_element.querySelectorAll(".bq-chip").forEach((c) => c.classList.toggle("on", c === chip));
    filter = chip.dataset.f;
    showAll = false;
    render();
  });
});

moreBtn.addEventListener("click", () => { showAll = !showAll; render(); });

list.addEventListener("click", (e) => {
  const b = e.target.closest("[data-builder]");
  if (b) { window.location.href = "/app/bom-builder?so=" + encodeURIComponent(b.dataset.builder); return; }
  const nb = e.target.closest("[data-newbom]");
  if (nb) { frappe.new_doc("BOM", { item: nb.dataset.newbom }); return; }
  const o = e.target.closest("[data-dt]");
  if (o) frappe.set_route("Form", o.dataset.dt, o.dataset.dn);
});

frappe.xcall("bom_work_queue", { part: "queue" }).then((r) => {
  items = r.items || [];
  const c = r.counts || {};
  meta.textContent = plural(items.length, "item", "items") + " · most urgent first · "
    + (c.ticket || 0) + " job tickets, " + (c.npd || 0) + " NPD, " + (c.product || 0) + " products";
  render();
}).catch(() => {
  meta.textContent = "";
  list.innerHTML = '<div class="bx-empty">Couldn\'t load the queue. Reload the page or check the BOM - Work Queue server script.</div>';
});

