script:
const hour = new Date().getHours();
const part = hour < 12 ? "Good morning" : (hour < 17 ? "Good afternoon" : "Good evening");
const first = (frappe.session.user_fullname || frappe.session.user || "").split(" ")[0];
root_element.querySelector(".cs-greet").textContent = part + ", " + first;
root_element.querySelector(".cs-sub").textContent =
  "Customer service, " + moment().format("dddd D MMMM YYYY");

const actions = {
  quotes: () => {
    frappe.route_options = { status: "Won" };
    frappe.set_route("List", "Savinda Quotation");
  },
  so: () => frappe.new_doc("Sales Order"),
  mr: () => frappe.new_doc("Material Request"),
  jt: () => frappe.new_doc("Production Plan"),
  npd: () => frappe.new_doc("NPD Request"),
};
root_element.querySelectorAll("[data-act]").forEach((btn) => {
  btn.addEventListener("click", () => actions[btn.dataset.act]());
});

