script:
const LIMIT = 8;
const esc = (s) => frappe.utils.escape_html(s == null ? "" : String(s));
const list = root_element.querySelector(".pj-list");
const sumEl = root_element.querySelector(".pj-sum");
const moreBtn = root_element.querySelector(".pj-more");
let jobs = [];
let filter = "all";
let showAll = false;

const mins = (m) => {
  m = Math.round(m || 0);
  const h = Math.floor(m / 60);
  return h ? h + "h " + (m % 60) + "m" : (m % 60) + "m";
};

const due = (j) => {
  const d = j.days_left;
  if (d === null || d === undefined) return { cls: "ok", text: "No required date" };
  if (d < 0) return { cls: "late", text: Math.abs(d) + (Math.abs(d) === 1 ? " day late" : " days late") };
  if (j.health === "risk") return { cls: "risk", text: d === 0 ? "Due today" : (d === 1 ? "Due tomorrow" : "Due in " + d + " days") };
  return { cls: "ok", text: "On track, " + frappe.datetime.str_to_user(j.req_date) };
};

const icon = { done: "&#10003;", run: "&#9654;", hold: "&#10074;&#10074;", ready: "&#9679;" };

const stepSub = (s) => {
  if (s.state === "done") return esc(s.workstation) + (s.hours ? " &middot; " + s.hours + "h" : "");
  if (s.state === "run") return esc(s.operator || s.workstation) + " &middot; " + mins(s.running_mins);
  if (s.state === "ready") return "Ready";
  return esc(s.workstation);
};

const note = (j) => {
  const held = j.steps.find((s) => s.state === "hold");
  if (held) return '<div class="pj-note hold">Stuck at ' + esc(held.operation) + " for " + held.hold_hours + "h on " + esc(held.workstation) + "</div>";
  if (j.health !== "ok") return '<div class="pj-note risk">' + (j.total - j.done) + " operations left &middot; " + due(j).text.toLowerCase() + "</div>";
  const running = j.steps.some((s) => s.state === "run");
  const ready = j.steps.find((s) => s.state === "ready");
  if (ready && !running) return '<div class="pj-note ready">Material transferred &middot; ready to start ' + esc(ready.operation) + " on " + esc(ready.workstation) + "</div>";
  return "";
};

const matches = (j) => {
  if (filter === "all") return true;
  if (filter === "late") return j.health !== "ok";
  if (filter === "hold") return j.stuck;
  return (j.pricing_type || "").toLowerCase() === filter;
};

const row = (j) => {
  const d = due(j);
  const pct = j.total ? Math.round((j.done / j.total) * 100) : 0;
  const type = (j.pricing_type || "").toLowerCase();
  let tags = "";
  if (j.pricing_type) tags += '<span class="pj-tag ' + type + '">' + esc(j.pricing_type) + "</span>";
  if (j.repeat) tags += '<span class="pj-tag">' + esc(j.repeat) + "</span>";
  if (j.callout) tags += '<span class="pj-tag">Callout</span>';
  let steps = "";
  j.steps.forEach((s, i) => {
    if (i > 0) steps += '<div class="pj-line ' + (j.steps[i - 1].state === "done" && s.state === "done" ? "done" : "") + '"></div>';
    steps += '<div class="pj-step ' + s.state + '" data-jc="' + esc(s.job_card) + '" title="' + esc(s.job_card) + '">'
      + '<div class="pj-dot ' + s.state + '">' + (icon[s.state] || (i + 1)) + "</div>"
      + '<div class="pj-lbl">' + esc(s.operation) + "</div>"
      + '<div class="pj-sub">' + stepSub(s) + "</div></div>";
  });
  const meta = [j.customer, j.title].filter(Boolean).map(esc).join(" &middot; ");
  return '<div class="pj-row">'
    + '<div class="pj-top"><div><span class="pj-id" data-pp="' + esc(j.name) + '">' + esc(j.name) + "</span>" + tags
    + '<div class="pj-meta">' + meta + "</div></div>"
    + '<div class="pj-right"><span class="pj-due ' + d.cls + '">' + d.text + "</span>"
    + '<div class="pj-meta">' + (pct ? pct + "% done" : "Not started") + "</div></div></div>"
    + '<div class="pj-steps">' + steps + "</div>" + note(j) + "</div>";
};

const render = () => {
  const shown = jobs.filter(matches);
  if (!shown.length) {
    list.innerHTML = '<div class="pj-empty">No jobs match this filter.</div>';
    moreBtn.hidden = true;
    return;
  }
  const visible = showAll ? shown : shown.slice(0, LIMIT);
  list.innerHTML = visible.map(row).join("");
  moreBtn.hidden = shown.length <= LIMIT;
  moreBtn.textContent = showAll ? "Show fewer" : "Show all " + shown.length + " jobs";
};

root_element.querySelectorAll(".pj-chip").forEach((chip) => {
  chip.addEventListener("click", () => {
    root_element.querySelectorAll(".pj-chip").forEach((c) => c.classList.toggle("on", c === chip));
    filter = chip.dataset.f;
    showAll = false;
    render();
  });
});

moreBtn.addEventListener("click", () => { showAll = !showAll; render(); });

list.addEventListener("click", (e) => {
  const jc = e.target.closest("[data-jc]");
  if (jc) return frappe.set_route("Form", "Job Card", jc.dataset.jc);
  const pp = e.target.closest("[data-pp]");
  if (pp) return frappe.set_route("Form", "Production Plan", pp.dataset.pp);
});

frappe.xcall("prod_job_journey").then((r) => {
  jobs = r.jobs || [];
  const s = r.summary || {};
  sumEl.innerHTML = "<span><b>" + (s.active || 0) + "</b>active</span>"
    + '<span style="color:#1D9E75"><b>' + (s.ok || 0) + "</b>on track</span>"
    + '<span style="color:#BA7517"><b>' + (s.risk || 0) + "</b>at risk</span>"
    + '<span style="color:#E24B4A"><b>' + (s.late || 0) + "</b>late</span>";
  if (!jobs.length) {
    list.innerHTML = '<div class="pj-empty">No active job tickets with job cards.</div>';
    return;
  }
  render();
}).catch(() => {
  list.innerHTML = '<div class="pj-empty">Couldn\'t load jobs. Reload the page or check the PROD - Job Journey server script.</div>';
});

style:
.pj { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 12px;
  padding: 14px 18px; color: var(--text-color); }
.pj-head { display: flex; justify-content: space-between; align-items: baseline; flex-wrap: wrap; gap: 10px; }
.pj-title { font-size: 15px; font-weight: 600; }
.pj-sum { display: flex; gap: 16px; font-size: 12px; flex-wrap: wrap; }
.pj-sum b { font-size: 16px; font-weight: 600; margin-right: 3px; }
.pj-chips { display: flex; gap: 6px; flex-wrap: wrap; margin: 12px 0 4px; }
.pj-chip { font: inherit; font-size: 12px; padding: 4px 10px; border-radius: 8px; cursor: pointer;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-muted); }
.pj-chip.on { border-color: #378ADD; color: #378ADD; background: rgba(55,138,221,.12); }
.pj-chip:focus-visible, .pj-more:focus-visible { outline: 2px solid #378ADD; outline-offset: 2px; }
.pj-row { border-top: 1px solid var(--border-color); padding: 12px 0; }
.pj-top { display: flex; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
.pj-id { font-size: 14px; font-weight: 600; cursor: pointer; }
.pj-id:hover { text-decoration: underline; }
.pj-tag { font-size: 11px; padding: 1px 7px; border-radius: 6px; margin-left: 5px;
  background: rgba(136,135,128,.15); color: var(--text-muted); }
.pj-tag.offset { background: rgba(127,119,221,.15); color: #7F77DD; }
.pj-tag.flexo { background: rgba(29,158,117,.15); color: #1D9E75; }
.pj-meta { font-size: 12px; color: var(--text-muted); margin-top: 2px; }
.pj-right { text-align: right; }
.pj-due { font-size: 11px; padding: 2px 8px; border-radius: 6px; white-space: nowrap; }
.pj-due.late { background: rgba(226,75,74,.15); color: #E24B4A; }
.pj-due.risk { background: rgba(239,159,39,.18); color: #BA7517; }
.pj-due.ok { background: rgba(29,158,117,.15); color: #1D9E75; }
.pj-steps { display: flex; align-items: flex-start; margin-top: 10px; overflow-x: auto; padding-bottom: 2px; }
.pj-step { display: flex; flex-direction: column; align-items: center; min-width: 78px; text-align: center; cursor: pointer; }
.pj-dot { width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center;
  justify-content: center; font-size: 12px; font-weight: 600; }
.pj-dot.done { background: rgba(29,158,117,.15); color: #1D9E75; }
.pj-dot.run { background: #1D9E75; color: #fff; box-shadow: 0 0 0 3px rgba(29,158,117,.25); }
.pj-dot.hold { background: rgba(226,75,74,.15); color: #E24B4A; box-shadow: 0 0 0 3px rgba(226,75,74,.12); }
.pj-dot.ready { background: rgba(55,138,221,.15); color: #378ADD; }
.pj-dot.todo { border: 1px solid var(--border-color); color: var(--text-muted); }
.pj-lbl { font-size: 11px; margin-top: 4px; line-height: 1.3; color: var(--text-muted); }
.pj-step.run .pj-lbl { color: var(--text-color); font-weight: 600; }
.pj-step.hold .pj-lbl { color: #E24B4A; }
.pj-sub { font-size: 10px; color: var(--text-muted); }
.pj-line { flex: 1; min-width: 10px; height: 2px; margin-top: 13px; background: var(--border-color); }
.pj-line.done { background: #5DCAA5; }
.pj-note { font-size: 12px; margin-top: 8px; padding: 6px 10px; border-radius: 8px; }
.pj-note.hold { background: rgba(226,75,74,.12); color: #E24B4A; }
.pj-note.risk { background: rgba(239,159,39,.15); color: #BA7517; }
.pj-note.ready { background: rgba(55,138,221,.12); color: #378ADD; }
.pj-empty { font-size: 13px; color: var(--text-muted); padding: 16px 0; text-align: center; }
.pj-more { display: block; width: 100%; margin-top: 4px; padding: 8px; font: inherit; font-size: 12px;
  border: none; border-top: 1px solid var(--border-color); background: transparent; color: #378ADD; cursor: pointer; }

html:
{%- set d = get_ticket_print_data(doc.name) -%}
{%- set h = d.header -%}
{%- macro fmt(v) -%}{{ '{:,.2f}'.format((v or 0)|float) }}{%- endmacro -%}
{%- macro fmtq(v) -%}
  {%- set n = (v or 0)|float -%}
  {%- if n == n|int -%}{{ n|int }}{%- else -%}{{ '{:g}'.format(n) }}{%- endif -%}
{%- endmacro -%}

<style>
  .jt { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222; }
  .jt-top { width:100%; border-collapse:collapse; margin-bottom:6px; }
  .jt-top td { vertical-align:top; }
  .jt-co { font-size:12px; font-weight:bold; }
  .jt-title { text-align:center; font-size:13px; font-weight:bold; }
  .jt-name { text-align:right; font-family:monospace; font-size:12px; font-weight:bold; }
  .info { width:100%; border-collapse:collapse; margin-bottom:8px; border:1px solid #333; }
  .info td { padding:3px 6px; border:1px solid #ccc; font-size:10.5px; vertical-align:top; }
  .info td.k { font-weight:bold; white-space:nowrap; width:12%; background:#f5f5f5; }
  .fin { margin:4px 0; font-size:10.5px; }
  .tbl { width:100%; border-collapse:collapse; margin:8px 0; font-size:10px; }
  .tbl th { background:#2b2b2b; color:#fff; padding:4px 5px; border:1px solid #555; text-align:center; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .tbl td { padding:3px 5px; border:1px solid #ddd; text-align:center; }
  .tbl td.l { text-align:left; }
  .mat th { background:#444; }
  .sec-lbl { font-weight:bold; font-size:10.5px; margin:8px 0 3px; }
  .sign { width:100%; border-collapse:collapse; margin-top:22px; }
  .sign td { text-align:center; font-size:10px; border-top:1px solid #333; padding-top:4px; width:20%; }
  .sign .nm { border:0; padding-bottom:18px; font-weight:bold; }
</style>

<div class="jt">
  <table class="jt-top">
    <tr>
      <td style="width:33%">
        {% if d.logo %}<img src="{{ d.logo }}" style="height:42px;display:block;margin-bottom:2px">{% endif %}
        <div class="jt-co">Savinda Graphic Systems (Pvt) Ltd.</div>
      </td>
      <td style="width:40%"><div class="jt-title">{{ 'Flexo' if d.is_flexo else 'Offset' }} Job Ticket ( No FSC )</div></td>
      <td style="width:27%"><div class="jt-name">{{ doc.name }}</div></td>
    </tr>
  </table>

  <table class="info">
    <tr>
      <td class="k">Job Title</td><td colspan="3">{{ h.job_title }}</td>
      <td class="k">Job No</td><td>{{ doc.name }}</td>
    </tr>
    <tr>
      <td class="k">Customer</td><td colspan="3">{{ h.customer }}</td>
      <td class="k">Job Date</td><td>{{ h.job_date }}</td>
    </tr>
    <tr>
      <td class="k">Art. No</td><td>{{ h.art_no }}</td>
      <td class="k">Art. Ver</td><td>{{ h.art_version }}</td>
      <td class="k">Req. Date</td><td>{{ h.req_date }}</td>
    </tr>
    <tr>
      <td class="k">PO No</td><td>{{ h.po_no }}</td>
      <td class="k">Colors</td><td>{{ h.colors }}</td>
      <td class="k">Quote No</td><td>{{ h.quote_no }}</td>
    </tr>
    <tr>
      <td class="k">Job Board</td><td colspan="3">{{ h.job_board }}</td>
      <td class="k">Color Ref.</td><td>{{ h.color_ref }}</td>
    </tr>
    <tr>
      <td class="k">Printing M/C</td><td>{{ h.printing_machine }}</td>
      <td class="k">Pricing</td><td>{{ 'Flexo' if d.is_flexo else 'Offset' }}</td>
      <td class="k">NPD Ref</td><td>{{ h.npd_request }}</td>
    </tr>
  </table>

  <div class="fin"><b>Finishings :</b> {{ h.finishings }}</div>
  <div class="fin"><b>Remarks :</b> {{ h.remarks }}</div>

  <table class="tbl">
    <thead>
      <tr>
        <th class="l" style="width:28%">Description</th>
        <th>Qty</th><th>Product Code</th><th>Batch/Lot</th>
        {% if d.is_flexo %}
        <th>Reel Length (m)</th><th>Reel Width (mm)</th><th>Reel Area (sq_m)</th><th>Slit Width (mm)</th>
        {% else %}
        <th>Full Sheets</th><th>Cut Sheets</th><th>F.Sheet Size</th><th>C.Sheet Size</th><th>Cuts</th><th>Ups</th>
        {% endif %}
      </tr>
    </thead>
    <tbody>
      {% for r in d.lines %}
      <tr>
        <td class="l">{{ r.description }}</td>
        <td>{{ fmtq(r.qty) }}</td><td>{{ r.product_code }}</td><td>{{ r.batch_no }}</td>
        {% if d.is_flexo %}
        <td>{{ fmtq(r.reel_length) }}</td><td>{{ fmtq(r.reel_width) }}</td><td>{{ fmtq(r.reel_area) }}</td><td>{{ r.slit_width }}</td>
        {% else %}
        <td>{{ fmtq(r.full_sheets) }}</td><td>{{ fmtq(r.cut_sheets) }}</td><td>{{ r.full_sheet_size }}</td><td>{{ r.cut_sheet_size }}</td><td>{{ r.cuts }}</td><td>{{ r.ups }}</td>
        {% endif %}
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="sec-lbl">BOM Materials (Non-Board Items)</div>
  <table class="tbl mat">
    <thead><tr><th class="l" style="width:60%">Item Name</th><th>Unit</th><th>Quantity</th><th>Wastage Qty</th></tr></thead>
    <tbody>
      {% for m in d.materials %}
      <tr><td class="l">{{ m.item_name }}</td><td>{{ m.uom }}</td><td>{{ fmtq(m.quantity) }}</td><td>{{ fmtq(m.wastage_qty) }}</td></tr>
      {% endfor %}
      {% if not d.materials %}<tr><td class="l">&nbsp;</td><td></td><td></td><td></td></tr>{% endif %}
    </tbody>
  </table>

  <table class="sign">
    <tr>{% for a in d.approvals %}<td class="nm">{{ a.by }}</td>{% endfor %}</tr>
    <tr>{% for a in d.approvals %}<td>{{ a.label }}<br><span style="color:#666">{{ a.on or '' }}</span></td>{% endfor %}</tr>
  </table>
</div>

