function sync_store_for_row(frm, row_key, selected_values, finishings) {
  const selected = new Set(selected_values);

  const keepers = (frm.doc[CFG.STORE_TABLE] || []).filter(
    d => d[CFG.STORE_ROW_REF_FIELD] !== row_key
  );

  frm.clear_table(CFG.STORE_TABLE);

  keepers.forEach(d => {
    const child = frm.add_child(CFG.STORE_TABLE);
    child[CFG.STORE_ROW_REF_FIELD] = d[CFG.STORE_ROW_REF_FIELD];
    child[CFG.STORE_FINISHING_FIELD] = d[CFG.STORE_FINISHING_FIELD];
    child[CFG.STORE_FINISHING_OP_FIELD] = d[CFG.STORE_FINISHING_OP_FIELD] || "";
    child[CFG.STORE_REMARK_FIELD] = d[CFG.STORE_REMARK_FIELD] || "";
    child[CFG.STORE_CHECKED_FIELD] = d[CFG.STORE_CHECKED_FIELD] ? 1 : 0;
  });

  finishings.forEach(f => {
    if (!selected.has(f.name)) return;

    const child = frm.add_child(CFG.STORE_TABLE);
    child[CFG.STORE_ROW_REF_FIELD] = row_key;
    child[CFG.STORE_FINISHING_FIELD] = f.name;
    child[CFG.STORE_FINISHING_OP_FIELD] = f.finishing_operation || f.name;
    child[CFG.STORE_REMARK_FIELD] = f.remark || "";
    child[CFG.STORE_CHECKED_FIELD] = 1;
  });

  frm.refresh_field(CFG.STORE_TABLE);
}

