            "Books - Digital",
            "Cartons - Digital",
            "Complementary Items - Digital",
            "Gift Boxes - Digital",
            "Other - Digital",
            "Paper Bags - Digital",
            "Paper Labels - Digital",
            "Self Adhesive Labels - Digital",
            "Other - Flexo",
            "Paper Labels - Flexo",
            "Self Adhesive Filmic Labels - Flexo",
            "Self Adhesive Paper Labels - Flexo",
            "Tags - Flexo",
            "Books - Offset",
            "Cartons - Offset",
            "Complementary Items - Offset",
            "Gift Boxes - Offset",
            "Other - Offset",
            "Paper Bags - Offset",
            "Paper Labels - Offset",
            "Self Adhesive Labels - Offset"
        ];

        const allowed_departments = [
            "Digital - SGSPL",
            "Flexo - SGSPL",
            "Offset - SGSPL"
        ];

        // Filter Department
        frm.set_query("custom_department", function() {
            return {
                filters: [
                    ["Department", "name", "in", allowed_departments]
                ]
            };
        });

        // Dynamic Item Group Filter
        frm.set_query("custom_item_group", function() {

            let parent_group = "";

            if (frm.doc.custom_department === "Digital - SGSPL") {
                parent_group = "Digital";
            }
            else if (frm.doc.custom_department === "Flexo - SGSPL") {
                parent_group = "Flexo";
            }
            else if (frm.doc.custom_department === "Offset - SGSPL") {
                parent_group = "Offset";
            }

            return {
                filters: [
                    ["Item Group", "name", "in", allowed_item_groups],
                    ["Item Group", "parent_item_group", "=", parent_group]
                ]
            };
        });

    },

    custom_department: function(frm) {
        // Clear item group when department changes
        frm.set_value("custom_item_group", null);
    }

});

