user = frappe.session.user
allowed = user == "Administrator" or frappe.db.exists("Has Role", {
    "parent": user,
    "parenttype": "User",
    "role": ["in", ['Production Team', 'System Manager']],
})
if not allowed:
    frappe.throw("You don't have access to this data.")

today = frappe.utils.nowdate()
now = frappe.utils.now_datetime()

plans = frappe.get_all(
    "Production Plan",
    filters={"docstatus": 1, "status": ["not in", ["Completed", "Closed", "Cancelled"]]},
    fields=["name", "custom_customer_name", "custom_job_title", "custom_pricing_type",
            "custom_repeat_or_new", "custom_is_callout", "custom_req_date"],
    order_by="custom_req_date asc",
    limit_page_length=80,
)
plan_names = [p.name for p in plans]

wo_plan = {}
for w in frappe.get_all(
    "Work Order",
    filters={"production_plan": ["in", plan_names or ["-"]], "docstatus": ["<", 2]},
    fields=["name", "production_plan"],
):
    wo_plan[w.name] = w.production_plan

cards = frappe.get_all(
    "Job Card",
    filters={"work_order": ["in", list(wo_plan.keys()) or ["-"]], "docstatus": ["<", 2]},
    fields=["name", "work_order", "operation", "workstation", "status", "docstatus",
            "for_quantity", "total_completed_qty", "total_time_in_mins",
            "expected_start_date", "creation", "modified"],
)

running = [c.name for c in cards if c.status == "Work In Progress"]
live = {}
if running:
    logs = frappe.get_all(
        "Job Card Time Log",
        filters={"parent": ["in", running], "parenttype": "Job Card", "to_time": ["is", "not set"]},
        fields=["parent", "employee", "from_time"],
    )
    emp_ids = list({l.employee: 1 for l in logs if l.employee}.keys())
    emp_names = {}
    for e in frappe.get_all("Employee", filters={"name": ["in", emp_ids or ["-"]]},
                            fields=["name", "employee_name"]):
        emp_names[e.name] = e.employee_name
    for l in logs:
        mins = 0
        if l.from_time:
            mins = frappe.utils.time_diff_in_hours(now, l.from_time) * 60
        live[l.parent] = {"operator": emp_names.get(l.employee, l.employee or ""), "mins": mins}

steps_by_plan = {}
for c in cards:
    plan = wo_plan.get(c.work_order)
    if plan not in steps_by_plan:
        steps_by_plan[plan] = []
    if c.docstatus == 1 or c.status == "Completed":
        state = "done"
    elif c.status == "Work In Progress":
        state = "run"
    elif c.status == "On Hold":
        state = "hold"
    elif c.status in ("Material Transferred", "Partially Transferred"):
        state = "ready"
    else:
        state = "todo"
    info = live.get(c.name, {})
    hold_hours = 0
    if state == "hold" and c.modified:
        hold_hours = frappe.utils.time_diff_in_hours(now, c.modified)
    steps_by_plan[plan].append({
        "job_card": c.name,
        "operation": c.operation,
        "workstation": c.workstation,
        "state": state,
        "hours": round((c.total_time_in_mins or 0) / 60.0, 1),
        "operator": info.get("operator", ""),
        "running_mins": round(info.get("mins", 0)),
        "hold_hours": round(hold_hours, 1),
        "sort": str(c.expected_start_date or c.creation),
    })

rank = {"late": 0, "risk": 1, "ok": 2}
jobs = []
for p in plans:
    steps = sorted(steps_by_plan.get(p.name, []), key=lambda s: s["sort"])
    if not steps:
        continue
    total = len(steps)
    done = len([s for s in steps if s["state"] == "done"])
    remaining = total - done
    days_left = None
    if p.custom_req_date:
        days_left = frappe.utils.date_diff(p.custom_req_date, today)
    if days_left is not None and days_left < 0 and remaining:
        health = "late"
    elif days_left is not None and remaining and days_left <= 2:
        health = "risk"
    else:
        health = "ok"
    stuck = len([s for s in steps if s["state"] == "hold"]) > 0
    jobs.append({
        "name": p.name,
        "customer": p.custom_customer_name or "",
        "title": p.custom_job_title or "",
        "pricing_type": p.custom_pricing_type or "",
        "repeat": p.custom_repeat_or_new or "",
        "callout": p.custom_is_callout or 0,
        "req_date": str(p.custom_req_date or ""),
        "days_left": days_left,
        "health": health,
        "stuck": stuck,
        "done": done,
        "total": total,
        "steps": steps,
        "rank": rank[health],
    })

jobs = sorted(jobs, key=lambda j: (j["rank"], j["days_left"] if j["days_left"] is not None else 9999))

frappe.response["message"] = {
    "jobs": jobs,
    "summary": {
        "active": len(jobs),
        "ok": len([j for j in jobs if j["health"] == "ok"]),
        "risk": len([j for j in jobs if j["health"] == "risk"]),
        "late": len([j for j in jobs if j["health"] == "late"]),
    },
}
